      .map((dy): Cell => [x + dx, y + dy]),
  );

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) =>
    survives(countLiveNeighbors(cell, liveCells)),
  );
  const births = liveCells
    .flatMap(neighborsOf)
    .filter(
      (candidate) =>
        !liveCells.some((cell) => isSameCell(cell, candidate)) &&
        countLiveNeighbors(candidate, liveCells) === 3,
    );
  return [...survivors, ...births];
}

