export type Cell = [x: number, y: number];

const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  x === otherX && y === otherY;

const isWithinOneStep = (coordinate: number, other: number): boolean =>
  Math.abs(coordinate - other) <= 1;

const isNeighbor = (cell: Cell, other: Cell): boolean => {
  const [x, y] = cell;
  const [otherX, otherY] = other;
  return (
    isWithinOneStep(x, otherX) &&
    isWithinOneStep(y, otherY) &&
    !isSameCell(cell, other)
  );
};

const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((other) => isNeighbor(cell, other)).length;

const neighborsOf = ([x, y]: Cell): Cell[] =>
  [-1, 0, 1].flatMap((dx) =>
    [-1, 0, 1]
      .filter((dy) => !(dx === 0 && dy === 0))
      .map((dy): Cell => [x + dx, y + dy]),
  );

const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
  liveCells.some((other) => isSameCell(cell, other));

const survives = (cell: Cell, liveCells: Cell[]): boolean => {
  const neighborCount = countLiveNeighbors(cell, liveCells);
  return neighborCount === 2 || neighborCount === 3;
};

const isBorn = (cell: Cell, liveCells: Cell[]): boolean =>
  !isAlive(cell, liveCells) && countLiveNeighbors(cell, liveCells) === 3;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
  const births = liveCells
    .flatMap(neighborsOf)
    .filter((candidate) => isBorn(candidate, liveCells));
  return [...survivors, ...births];
}

